package com.araujovito.creditradar.config;
import com.araujovito.creditradar.asset.*;
import com.araujovito.creditradar.credit.*;
import com.araujovito.creditradar.research.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.*;

@Configuration public class DemoData {
 @Bean CommandLineRunner load(TrackedAssetRepository assets,CreditPositionRepository positions,SourceDocumentRepository documents,PortfolioSnapshotRepository snapshots){return args->{if(assets.count()>0)return;
  var kncr=assets.save(new TrackedAsset("KNCR11","Kinea Rendimentos Imobiliários",AssetType.FII,"Kinea"));
  var historicDate=LocalDate.of(2024,11,30); var historic=documents.save(new SourceDocument(kncr,"Carta do Gestor — novembro de 2024",historicDate,"https://www.kinea.com.br/wp-content/uploads/2024/12/KNCR_Carta-do-Gestor_11-2024.pdf"));
  position(positions,kncr,historic,"Hotel Hilton Copacabana","Hotelaria","CDI + 2,00%",90.10,null,historicDate); position(positions,kncr,historic,"JSRE — Ed. Rochaverá","Escritórios","CDI + 2,60%",12.90,null,historicDate);
  var currentDate=LocalDate.of(2026,7,31); var current=documents.save(new SourceDocument(kncr,"Relatório Gerencial — julho de 2026",currentDate,"https://fnet.bmfbovespa.com.br/fnet/publico/exibirDocumento?cvm=true&id=1283565")); snapshots.save(new PortfolioSnapshot(kncr,current,currentDate,new BigDecimal("83.60"),new BigDecimal("12.70"),new BigDecimal("3.70")));
  position(positions,kncr,current,"JHSF Malls II","Shoppings","CDI + 2,25%",425.5,3.9,currentDate); position(positions,kncr,current,"JHSF Malls","Shoppings","CDI + 2,06%",321.0,2.9,currentDate); position(positions,kncr,current,"Brookfield BR12","Imobiliário","CDI + 2,03%",308.9,2.8,currentDate); position(positions,kncr,current,"Brookfield — Ed. Sigma","Escritórios","CDI + 1,78%",299.5,2.7,currentDate); position(positions,kncr,current,"Almeida Júnior","Shoppings","CDI + 1,76%",205.8,1.9,currentDate); position(positions,kncr,current,"Brookfield — Ed. Passeio Paulista","Escritórios","CDI + 1,73%",191.0,1.7,currentDate); position(positions,kncr,current,"TRX — O Parque","Escritórios","CDI + 1,26%",176.6,1.6,currentDate); position(positions,kncr,current,"CPOF — Ed. FL Plaza","Escritórios","CDI + 2,30%",173.2,1.6,currentDate); position(positions,kncr,current,"JW Marriott Hotel","Hotelaria","CDI + 1,60%",155.7,1.4,currentDate); position(positions,kncr,current,"Brookfield — Ed. Sucupira","Escritórios","CDI + 1,42%",145.7,1.3,currentDate); position(positions,kncr,current,"JRM — Irmãos Muffato","Varejo","CDI + 2,52%",145.5,1.3,currentDate); position(positions,kncr,current,"Even Estoque","Residencial","CDI + 2,36%",143.8,1.3,currentDate); position(positions,kncr,current,"Edifício O Parque","Escritórios","CDI + 2,50%",142.9,1.3,currentDate); position(positions,kncr,current,"Ed. Eldorado","Escritórios","CDI + 2,19%",135.0,1.2,currentDate); position(positions,kncr,current,"Allos I","Shoppings","CDI + 1,44%",79.3,0.7,currentDate); position(positions,kncr,current,"MRV — Pro-soluto 429","Residencial","CDI + 3,50%",73.8,0.7,currentDate); position(positions,kncr,current,"HGBS — Bauru Shopping","Shoppings","CDI + 1,60%",68.1,0.6,currentDate); position(positions,kncr,current,"BRCR — Torre Almirante","Escritórios","CDI + 2,50%",66.3,0.6,currentDate); position(positions,kncr,current,"HSLG — BTS Meli","Logístico","CDI + 2,25%",63.4,0.6,currentDate);
 };}
 private void position(CreditPositionRepository positions,TrackedAsset asset,SourceDocument source,String issuer,String sector,String indexer,double amount,Double weight,LocalDate date){positions.save(new CreditPosition(asset,source,InstrumentType.CRI,issuer,sector,indexer,null,null,weight==null?null:BigDecimal.valueOf(weight),BigDecimal.valueOf(amount),"Não informado na tabela",date));}
 @Bean CommandLineRunner groupProfiles(EconomicGroupProfileRepository profiles){return args->{if(profiles.count()>0)return;
  profiles.save(new EconomicGroupProfile("Brookfield","Imobiliário","Grupo global com presença pública","","https://www.brookfield.com/pt-br/sobre-n%C3%B3s/recursos/imobili%C3%A1rio","O agrupamento reúne posições Brookfield identificadas na carteira do KNCR11.","MÉDIA"));
  profiles.save(new EconomicGroupProfile("JHSF","Shoppings e hospitalidade","Companhia aberta","JHSF3","https://ri.jhsf.com.br/outras-informacoes/perguntas-frequentes/","As posições JHSF Malls e JHSF Malls II foram agrupadas pela denominação informada no relatório.","ALTA"));
  profiles.save(new EconomicGroupProfile("MRV","Incorporação residencial","Companhia aberta","MRVE3","https://ri.mrv.com.br/governanca-corporativa/visao-geral/","A posição MRV Pro-soluto foi reportada no KNCR11; a identidade jurídica da operação deve ser confirmada no documento do CRI.","MÉDIA"));
  profiles.save(new EconomicGroupProfile("Allos","Shoppings","Companhia aberta","ALOS3","https://ri.allos.com.br/","A posição Allos I foi identificada no relatório do KNCR11.","ALTA"));
  profiles.save(new EconomicGroupProfile("TRX — O Parque","Imobiliário","Estrutura de crédito a confirmar","","https://fnet.bmfbovespa.com.br/fnet/publico/exibirDocumento?cvm=true&id=1242367","O relatório de junho de 2026 registra o investimento no CRI TRX — O Parque; a relação societária deve ser verificada nos documentos da operação.","MÉDIA"));
 };}
 @Bean CommandLineRunner debtorResearch(DebtorResearchRepository research){return args->{if(research.count()>0)return;
  add(research,"JHSF Malls II","FONTE PÚBLICA","Vínculo de grupo econômico identificado pela denominação da operação.","https://ri.jhsf.com.br/outras-informacoes/perguntas-frequentes/"); add(research,"JHSF Malls","FONTE PÚBLICA","Vínculo de grupo econômico identificado pela denominação da operação.","https://ri.jhsf.com.br/outras-informacoes/perguntas-frequentes/");
  add(research,"Brookfield BR12","GRUPO MAPEADO","Grupo Brookfield identificado; a SPE devedora exige confirmação no documento da emissão.","https://www.brookfield.com/pt-br/sobre-n%C3%B3s/recursos/imobili%C3%A1rio"); add(research,"Brookfield — Ed. Sigma","GRUPO MAPEADO","Grupo Brookfield identificado; a SPE devedora exige confirmação no documento da emissão.","https://www.brookfield.com/pt-br/sobre-n%C3%B3s/recursos/imobili%C3%A1rio"); add(research,"Brookfield — Ed. Passeio Paulista","GRUPO MAPEADO","Grupo Brookfield identificado; a SPE devedora exige confirmação no documento da emissão.","https://www.brookfield.com/pt-br/sobre-n%C3%B3s/recursos/imobili%C3%A1rio"); add(research,"Brookfield — Ed. Sucupira","GRUPO MAPEADO","Grupo Brookfield identificado; a SPE devedora exige confirmação no documento da emissão.","https://www.brookfield.com/pt-br/sobre-n%C3%B3s/recursos/imobili%C3%A1rio");
  add(research,"Almeida Júnior","FONTE PÚBLICA","Operadora de shopping centers com site e RI públicos; CNPJ exibido na fonte.","https://almeidajunior.com.br/pt-br/"); add(research,"JRM — Irmãos Muffato","FONTE PÚBLICA","Grupo Muffato identifica Irmãos Muffato & Cia Ltda. e CNPJ em seu site oficial.","https://www.grupomuffato.com.br/"); add(research,"Even Estoque","FONTE PÚBLICA","Grupo Even possui RI público; a SPE específica precisa ser validada na documentação do CRI.","https://ri.even.com.br/"); add(research,"Allos I","FONTE PÚBLICA","ALLOS possui RI público; a entidade específica da operação requer confirmação documental.","https://ri.allos.com.br/"); add(research,"MRV — Pro-soluto 429","FONTE PÚBLICA","Grupo MRV possui RI público; a operação pró-soluto exige confirmação da entidade emissora.","https://ri.mrv.com.br/governanca-corporativa/visao-geral/");
  add(research,"TRX — O Parque","DOCUMENTO DO CRI","A operação é descrita no relatório; a relação societária e a SPE devem ser verificadas no documento do CRI.","https://fnet.bmfbovespa.com.br/fnet/publico/exibirDocumento?cvm=true&id=1242367"); add(research,"CPOF — Ed. FL Plaza","DOCUMENTO DO CRI","Nome de operação/imóvel; requer documento de emissão para identificar a entidade jurídica.","https://fnet.bmfbovespa.com.br/fnet/publico/exibirDocumento?cvm=true&id=1283565"); add(research,"JW Marriott Hotel","DOCUMENTO DO CRI","Marca e imóvel não confirmam isoladamente a SPE devedora.","https://fnet.bmfbovespa.com.br/fnet/publico/exibirDocumento?cvm=true&id=1283565"); add(research,"Edifício O Parque","DOCUMENTO DO CRI","Imóvel identificado no relatório; requer documento de emissão para a devedora legal.","https://fnet.bmfbovespa.com.br/fnet/publico/exibirDocumento?cvm=true&id=1283565"); add(research,"Ed. Eldorado","DOCUMENTO DO CRI","Imóvel identificado no relatório; requer documento de emissão para a devedora legal.","https://fnet.bmfbovespa.com.br/fnet/publico/exibirDocumento?cvm=true&id=1283565"); add(research,"HGBS — Bauru Shopping","DOCUMENTO DO CRI","Nome sugere estrutura vinculada a ativo/fundo; requer documento de emissão.","https://fnet.bmfbovespa.com.br/fnet/publico/exibirDocumento?cvm=true&id=1283565"); add(research,"BRCR — Torre Almirante","DOCUMENTO DO CRI","Nome sugere estrutura vinculada a ativo/fundo; requer documento de emissão.","https://fnet.bmfbovespa.com.br/fnet/publico/exibirDocumento?cvm=true&id=1283565"); add(research,"HSLG — BTS Meli","DOCUMENTO DO CRI","Nome sugere estrutura vinculada a ativo/fundo; requer documento de emissão.","https://fnet.bmfbovespa.com.br/fnet/publico/exibirDocumento?cvm=true&id=1283565");
 };}
 private void add(DebtorResearchRepository research,String debtor,String status,String assessment,String source){research.save(new DebtorResearch(debtor,status,assessment,source));}
}
